from __future__ import annotations


from typing import Any
from abc import ABCMeta, abstractmethod

import warnings

import pyopencl as cl
import cupy as cp
import numpy as np


class CoeffBackend(metaclass=ABCMeta):
    """
    The coefficient based backend.

    This routine collection is implemented as a class, because for specific
    backend implementations, auxilliary variables, special libraries or
    initialization might be required.
    """

    def __init__(self, *args, **kwargs):
        print(f"Backend '{self.__class__.__name__}': __init__()")

    def coeff_add(
        self, co_r: Any, co_a: Any, co_b: Any, size: int, dtype: str = "f64"
    ) -> None:
        """Adds operands op_a and op_b, write result to op_r."""
        return self.coeff_linop(
            co_r, None, co_a, None, co_b, size=size, dtype=dtype
        )

    def coeff_smul(
        self, co_r: Any, co_a: Any, scal, size: int, dtype: str = "f64"
    ) -> None:
        """Scalar-multiply co_a with scal, write result to co_r."""
        return self.coeff_linop(
            co_r, scal, co_a, None, None, size=size, dtype=dtype
        )

    def coeff_to_zero(self, coeff_like: Any, size: int, dtype: str = "f64"):
        """Set the passed coefficient vector to zero."""
        if size is None:
            size = len(coeff_like)
        self.coeff_smul(coeff_like, coeff_like, 0.0, size=size, dtype=dtype)

    def coeff_copy_data(
        self, targ: Any, source: Any, size: int, dtype: str = "f64"
    ):
        """Copy the data from source to targ."""
        self.coeff_linop(targ, None, source, size=size, dtype=dtype)

    def coeff_free(self, reference, size: int, dtype: str = "f64"):
        """free the memory at ref."""
        return None

    def coeff_allclose(
        self,
        coeff_a,
        coeff_b,
        atol: float,
        rtol: float,
        size: int,
        dtype: str = "f64",
    ) -> bool:
        """
        Perform the all-close-check:
        Check if the values are all sufficiently close by checking, if
        |a - b|² <= atol² + rtol² (|a|² + |b|²) / 4
        is fulfilled for all coefficients."""
        return np.allclose(
            self.coeff_to_numpy(coeff_a, size=size, dtype=dtype),
            self.coeff_to_numpy(coeff_b, size=size, dtype=dtype),
            atol=atol,
            rtol=rtol,
        )

    ###########################################################################
    #
    # ABSTRACT METHODS
    # ================
    #

    @abstractmethod
    def coeff_new_array(self, size: int, dtype: str = "f64") -> Any:
        """Create an empty coeff array."""

    @abstractmethod
    def coeff_from_numpy(
        self,
        coeff_like: Any,
        nparray: np.ndarray,
        size: int,
        dtype: str = "f64",
    ) -> None:
        """Fill the coeffs from a numpy array."""

    @abstractmethod
    def coeff_to_numpy(
        self, coeff_like: Any, size: int, dtype: str = "f64"
    ) -> np.ndarray:
        """Export the coeffs as a numpy array."""

    @abstractmethod
    def coeff_linop(
        self,
        arr_r: Any,
        /,
        scal_a: float | None,
        arr_x: Any,
        scal_b: float | None,
        arr_y: Any = None,
        *,
        size: int,
        dtype: str = "f64",
        inplace: bool = False,
    ):
        """
        Performs the basic linear operation
            r = a * x (+ b * y)
        where and a and b are scalar and x and y are a coeff array.
        If the inplace flag is set, perform
            r += a * x (+ b * y)
        instead.

        if the scalars are to be ignored, pass None. This may cause a default
        value of 1 to take this place.
        """


###############################################################################


class PurePyCoeffBackend(CoeffBackend):
    """implement the backend for 'PurePy'"""

    def coeff_new_array(self, size: int, dtype: str = "f64"):
        match dtype:
            case "f32":
                return [0.0 for _ in range(size)]
            case "f64":
                return [0.0 for _ in range(size)]
            case "i32":
                return [0 for _ in range(size)]
            case "i64":
                return [0 for _ in range(size)]
            case _:
                raise ValueError(f"dtype {dtype} not understood")

    def coeff_from_numpy(
        self,
        coeff_like: Any,
        nparray: np.ndarray,
        size: int,
        dtype: str = "f64",
    ) -> None:
        if dtype in ("f32", "f64"):
            if nparray.dtype in [np.float32, np.float64]:
                for num, val in enumerate(nparray):
                    coeff_like[num] = float(val)
            else:
                raise ValueError(
                    f"Wrong input datatype {nparray.dtype} for dtype {dtype}."
                )
        elif dtype in ("i32", "i64"):
            if nparray.dtype in [np.int32, np.int64]:
                for num, val in enumerate(nparray):
                    coeff_like[num] = int(val)
            else:
                raise ValueError(
                    f"Wrong input datatype {nparray.dtype} for dtype {dtype}."
                )
        else:
            raise ValueError(f"dtype {dtype} not understood")

    def coeff_to_numpy(
        self, coeff_like: Any, size: int, dtype: str = "f64"
    ) -> np.ndarray:
        match dtype:
            case "f32":
                return np.array(coeff_like, dtype=np.float32)
            case "f64":
                return np.array(coeff_like, dtype=np.float64)
            case "i32":
                return np.array(coeff_like, dtype=np.int32)
            case "i64":
                return np.array(coeff_like, dtype=np.int64)
            case _:
                raise ValueError(f"dtype {dtype} not understood")

    def coeff_linop(
        self,
        arr_r: Any,
        /,
        scal_a: float | None,
        arr_x: Any,
        scal_b: float | None,
        arr_y: Any = None,
        *,
        size: int,
        dtype: str = "f64",
        inplace: bool = False,
    ):
        match (inplace, scal_a):
            case (True, None):
                for num in range(size):
                    arr_r[num] += arr_x[num]
            case (True, scal_a):
                for num in range(size):
                    arr_r[num] += scal_a * arr_x[num]
            case (False, None):
                for num in range(size):
                    arr_r[num] = arr_x[num]
            case (False, scal_a):
                for num in range(size):
                    arr_r[num] = scal_a * arr_x[num]

        match (scal_b, arr_y):
            case (None, None):
                return
            case (None, arr_y):
                for num in range(size):
                    arr_r[num] += arr_y[num]
            case (scal_b, None):
                for num in range(size):
                    arr_r[num] += scal_b
            case (scal_b, arr_y):
                for num in range(size):
                    arr_r[num] += scal_b * arr_y[num]


class NumpyCoeffBackend(CoeffBackend):
    """implement the backend for 'Numpy'"""

    def coeff_new_array(self, size: int, dtype: str = "f64"):
        match dtype:
            case "f32":
                return np.zeros(size, dtype=np.float32)
            case "f64":
                return np.zeros(size, dtype=np.float64)
            case "i32":
                return np.zeros(size, dtype=np.int32)
            case "i64":
                return np.zeros(size, dtype=np.int64)
            case _:
                raise ValueError(f"dtype {dtype} not understood")

    def coeff_from_numpy(
        self,
        coeff_like: Any,
        nparray: np.ndarray,
        size: int,
        dtype: str = "f64",
    ) -> None:
        if dtype in ("f32", "f64"):
            if nparray.dtype in [np.float32, np.float64]:
                coeff_like[:] = nparray
            else:
                raise ValueError(
                    f"Wrong input datatype {nparray.dtype} for dtype {dtype}."
                )
        elif dtype in ("i32", "i64"):
            if nparray.dtype in [np.int32, np.int64]:
                coeff_like[:] = nparray
            else:
                raise ValueError(
                    f"Wrong input datatype {nparray.dtype} for dtype {dtype}."
                )
        else:
            raise ValueError(f"dtype {dtype} not understood")

    def coeff_to_numpy(
        self, coeff_like: Any, size: int, dtype: str = "f64"
    ) -> np.ndarray:
        match dtype:
            case "f32":
                return np.array(coeff_like, dtype=np.float32)
            case "f64":
                return np.array(coeff_like, dtype=np.float64)
            case "i32":
                return np.array(coeff_like, dtype=np.int32)
            case "i64":
                return np.array(coeff_like, dtype=np.int64)
            case _:
                raise ValueError(f"dtype {dtype} not understood")

    def coeff_linop(
        self,
        arr_r: Any,
        /,
        scal_a: float | None,
        arr_x: Any,
        scal_b: float | None,
        arr_y: Any = None,
        *,
        size: int,
        dtype: str = "f64",
        inplace: bool = False,
    ):
        match (inplace, scal_a):
            case (True, None):
                arr_r += arr_x
            case (True, scal_a):
                arr_r += scal_a * arr_x
            case (False, None):
                arr_r = arr_x
            case (False, scal_a):
                arr_r = scal_a * arr_x

        match (scal_b, arr_y):
            case (None, None):
                return
            case (None, arr_y):
                arr_r += arr_y
            case (scal_b, None):
                arr_r += scal_b
            case (scal_b, arr_y):
                arr_r += scal_b * arr_y


class FortranCoeffBackend(CoeffBackend):
    """implement the backend for 'Fortran'"""

    def coeff_new_array(self, size: int, dtype: str = "f64"):
        return NumpyCoeffBackend.coeff_new_array(self, size=size, dtype=dtype)

    def coeff_from_numpy(
        self,
        coeff_like: Any,
        nparray: np.ndarray,
        size: int,
        dtype: str = "f64",
    ) -> None:
        return NumpyCoeffBackend.coeff_from_numpy(
            self, coeff_like=coeff_like, nparray=nparray, size=size, dtype=dtype
        )

    def coeff_to_numpy(
        self, coeff_like: Any, size: int, dtype: str = "f64"
    ) -> np.ndarray:
        return NumpyCoeffBackend.coeff_to_numpy(
            self, coeff_like=coeff_like, size=size, dtype=dtype
        )

    def coeff_linop(
        self,
        arr_r: Any,
        /,
        scal_a: float | None,
        arr_x: Any,
        scal_b: float | None,
        arr_y: Any = None,
        *,
        size: int,
        dtype: str = "f64",
        inplace: bool = False,
    ):
        return NumpyCoeffBackend.coeff_linop(
            self,
            arr_r,
            scal_a=scal_a,
            arr_x=arr_x,
            scal_b=scal_b,
            arr_y=arr_y,
            size=size,
            dtype=dtype,
            inplace=inplace,
        )


class CupyCoeffBackend(CoeffBackend):
    """implement the backend for 'Cupy'"""

    def coeff_new_array(self, size: int, dtype: str = "f64"):
        match dtype:
            case "f32":
                return cp.zeros(size, dtype=cp.float32)
            case "f64":
                return cp.zeros(size, dtype=cp.float64)
            case "i32":
                return cp.zeros(size, dtype=cp.int32)
            case "i64":
                return cp.zeros(size, dtype=cp.int64)
            case _:
                raise ValueError(f"dtype {dtype} not understood")

    def coeff_from_numpy(
        self,
        coeff_like: Any,
        nparray: np.ndarray,
        size: int,
        dtype: str = "f64",
    ) -> None:
        if dtype in ("f32", "f64"):
            if nparray.dtype in [np.float32, np.float64]:
                coeff_like[:] = cp.asarray(nparray)
            else:
                raise ValueError(
                    f"Wrong input datatype {nparray.dtype} for dtype {dtype}."
                )
        elif dtype in ("i32", "i64"):
            if nparray.dtype in [np.int32, np.int64]:
                coeff_like[:] = cp.asarray(nparray)
            else:
                raise ValueError(
                    f"Wrong input datatype {nparray.dtype} for dtype {dtype}."
                )
        else:
            raise ValueError(f"dtype {dtype} not understood")

    def coeff_to_numpy(
        self, coeff_like: Any, size: int, dtype: str = "f64"
    ) -> np.ndarray:
        match dtype:
            case "f32":
                return np.array(coeff_like.asnumpy(), dtype=np.float32)
            case "f64":
                return np.array(coeff_like.asnumpy(), dtype=np.float64)
            case "i32":
                return np.array(coeff_like.asnumpy(), dtype=np.int32)
            case "i64":
                return np.array(coeff_like.asnumpy(), dtype=np.int64)
            case _:
                raise ValueError(f"dtype {dtype} not understood")

    def coeff_linop(
        self,
        arr_r: Any,
        /,
        scal_a: float | None,
        arr_x: Any,
        scal_b: float | None,
        arr_y: Any = None,
        *,
        size: int,
        dtype: str = "f64",
        inplace: bool = False,
    ):
        match (inplace, scal_a):
            case (True, None):
                arr_r += arr_x
            case (True, scal_a):
                arr_r += scal_a * arr_x
            case (False, None):
                arr_r = arr_x
            case (False, scal_a):
                arr_r = scal_a * arr_x

        match (scal_b, arr_y):
            case (None, None):
                return
            case (None, arr_y):
                arr_r += arr_y
            case (scal_b, None):
                arr_r += scal_b
            case (scal_b, arr_y):
                arr_r += scal_b * arr_y


class OpenClCoeffBackend(CoeffBackend):
    """implement the backend for 'OpenCl'"""

    def __init__(self, *args, **kwargs):
        super().__init__(self, *args, **kwargs)

        self._cl_cntxt = cl.create_some_context()
        self._cl_queue = cl.CommandQueue(self._cl_cntxt)

        self._cl_mflag = cl.mem_flags

    def coeff_new_array(self, size: int, dtype: str = "f64"):
        try:
            read_write = self._cl_mflag.READ_WRITE

            floats = cl.Buffer(
                self._cl_cntxt,
                read_write,
                size=8 * size,  # size in bytes
            )
        except cl.Error as e:
            warnings.warn("Failed to create OpenCL buffer: {}".format(str(e)))
            return (None, None)
        return floats

    def coeff_from_numpy(
        self,
        coeff_like: Any,
        nparray: np.ndarray,
        size: int,
        dtype: str = "f64",
    ) -> None:
        raise NotImplementedError()

    def coeff_to_numpy(
        self, coeff_like: Any, size: int, dtype: str = "f64"
    ) -> np.ndarray:
        raise NotImplementedError()

    def coeff_linop(
        self,
        arr_r: Any,
        /,
        scal_a: float | None,
        arr_x: Any,
        scal_b: float | None,
        arr_y: Any = None,
        *,
        size: int,
        dtype: str = "f64",
        inplace: bool = False,
    ):
        raise NotImplementedError()
